(()=>{'use strict';const B='https://woongbi-quote-api.woongbts.workers.dev';let C=null,P=null;async function post(body){let last;for(let i=0;i<3;i++){const ctl=typeof AbortController!=='undefined'?new AbortController():null,t=ctl?setTimeout(()=>ctl.abort(),8000):0;try{const r=await fetch(B+'/quote/internet',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctl?.signal});const d=await r.json().catch(()=>({}));if(r.ok&&d?.ok===true)return d;last=new Error(d?.error||('internet-api-'+r.status))}catch(e){last=e}finally{if(t)clearTimeout(t)}if(i<2)await new Promise(r=>setTimeout(r,500*(i+1)))}throw last||new Error('internet-api-unavailable')}async function loadCatalog(){if(C)return C;if(P)return P;P=post({mode:'catalog'}).then(d=>{C=d.catalog;document.documentElement.dataset.internetApi='ready';window.dispatchEvent(new CustomEvent('woongbi:internet-api-ready',{detail:C}));return C}).catch(e=>{document.documentElement.dataset.internetApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:internet-api-unavailable'));throw e}).finally(()=>{P=null});return P}async function options(internet_product_id,tv_product_id='none'){return(await post({mode:'options',internet_product_id,tv_product_id})).options}async function quote({internet_product_id,tv_product_id='none',tv_count=1,wired_bundle_id='none',mobile_bundle_id='none'}){return(await post({internet_product_id,tv_product_id,tv_count:Number(tv_count)||1,wired_bundle_id,mobile_bundle_id})).quote}async function compare({speed_mbps=500,include_tv=false,tv_count=1}){return(await post({mode:'compare',speed_mbps:Number(speed_mbps)||500,include_tv:Boolean(include_tv),tv_count:Number(tv_count)||1})).items||[]}window.WoongbiInternetApi={loadCatalog,options,quote,compare};})();
